/* EVOLVE Beta — app web estático. Dados locais por padrão; Supabase/Google são opcionais.
 * Sem credenciais de terceiros embutidas ou escrita automática na agenda.
 */
(()=>{'use strict';
const C=window.EVOLVE_CONFIG||{}, KEY='evolve_beta_v1', themeKey='evolve_beta_theme_v1';
const storage=(()=>{try{const s=window.localStorage;s.getItem('__evolve_probe__');return s}catch(e){const m=new Map();return {getItem:k=>m.has(k)?m.get(k):null,setItem:(k,v)=>m.set(k,String(v)),removeItem:k=>m.delete(k)}}})();
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const iconPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',spark:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3z"/><path d="m19 18 .8 2.2L22 21l-2.2.8L19 24l-.8-2.2L16 21l2.2-.8z"/>',settings:'<path d="M12 3v2m0 14v2M4.2 4.2l1.4 1.4m12.8 12.8 1.4 1.4M3 12h2m14 0h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/><circle cx="12" cy="12" r="4"/>',moon:'<path d="M20 14.3A8 8 0 0 1 9.7 4 8.1 8.1 0 1 0 20 14.3z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',left:'<path d="m15 18-6-6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',check:'<path d="m5 12 5 5L20 7"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',flame:'<path d="M12 22c-4 0-7-3-7-7 0-3 2-5 3-7 0 3 2 4 2 4 0-4 2-7 4-10 0 4 5 7 5 13 0 4-3 7-7 7z"/>',book:'<path d="M12 6c-2-2-6-2-9-1v14c3-1 7-1 9 1 2-2 6-2 9-1V5c-3-1-7-1-9 1zm0 0v14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 1 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M3 10V5a2 2 0 0 1 2-2h12M16 15h5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12H4v9h16v-9h-1"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-5 3-7 8-7s8 2 8 7"/>',wifi:'<path d="M3 10a14 14 0 0 1 18 0M6 13a9 9 0 0 1 12 0M9 16a4 4 0 0 1 6 0"/><circle cx="12" cy="20" r="1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',edit:'<path d="m4 16-1 5 5-1L20 8l-4-4L4 16z"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',refresh:'<path d="M20 8a8 8 0 1 0 1 6M20 3v5h-5"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3v-8a9 9 0 1 1 19-3z"/>',shield:'<path d="M12 2 4 6v6c0 6 4 9 8 10 4-1 8-4 8-10V6z"/><path d="m9 12 2 2 4-4"/>',external:'<path d="M13 4h7v7M11 13l9-9M20 14v6H4V4h6"/>',coffee:'<path d="M4 7h13v8a6 6 0 0 1-13 0zM17 9h2a3 3 0 0 1 0 6h-2M3 21h16"/>',chart:'<path d="M4 21V3m0 18h17M7 16l5-5 4 3 5-9"/>',logout:'<path d="M10 3H4v18h6m4-4 5-5-5-5m5 5H9"/>'};
function ico(name,size=20){return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.spark}</svg>`}
function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const CATS={health:{label:'Saúde',emoji:'🫀'},mind:{label:'Aprendizado',emoji:'📚'},business:{label:'Negócios',emoji:'🚀'},life:{label:'Vida pessoal',emoji:'💜'},home:{label:'Organização',emoji:'🏠'},other:{label:'Outro',emoji:'✨'}};
const DOW=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];const DOW_LONG=['domingo','segunda','terça','quarta','quinta','sexta','sábado'];
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const fromKey=k=>new Date(`${k}T12:00:00`);const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function plus(k,n){const d=fromKey(k);d.setDate(d.getDate()+n);return key(d)}
function weekStart(k){const d=fromKey(k);d.setDate(d.getDate()-((d.getDay()+6)%7));return key(d)}
function daysBetween(a,b){return Math.round((fromKey(b)-fromKey(a))/86400000)}
function formatDate(k,long=false){return fromKey(k).toLocaleDateString('pt-BR',long?{weekday:'long',day:'numeric',month:'long'}:{day:'2-digit',month:'short'})}
function uuid(){return (crypto?.randomUUID?crypto.randomUUID():'ev'+Date.now().toString(36)+Math.random().toString(36).slice(2))}
function minutes(t){const a=String(t||'0:0').split(':').map(Number);return a[0]*60+a[1]}
function clock(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function clamp(n,min,max){return Math.max(min,Math.min(max,n))}
function percent(n,d){return d?clamp(Math.round((n/d)*100),0,100):0}
function textValue(el){return String(el?.value||'').trim()}
function safeNum(el,def=0){let v=Number(el?.value);return Number.isFinite(v)?v:def}
function notify(msg){let d=document.createElement('div');d.className='toast';d.textContent=msg;$('#toastRoot').append(d);setTimeout(()=>d.remove(),4500)}
function download(name,blob,type='application/octet-stream'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([blob],{type}));a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function baseState(){return {version:2,profile:{name:'',wake:'07:00',sleep:'23:30',workStart:'09:00',workEnd:'18:00',officeDays:[5],commute:50,weekHours:40,priorities:['health','business','life']},goals:[],events:[],logs:{},reviews:[],feedback:[],chat:[],created:today(),updated:today(),setup:false,mode:'local'}}
function sampleState(){const s=baseState();s.profile.name='Alex';s.profile.officeDays=[5];s.goals=[{id:'g1',name:'Movimentar o corpo',category:'health',weekly:3,duration:25,priority:1,preferred:'morning',days:[1,3,5],created:today(),description:'Calistenia ou caminhada leve'},{id:'g2',name:'Criar meu projeto',category:'business',weekly:2,duration:60,priority:2,preferred:'evening',days:[1,4],created:today(),description:'Progredir em um projeto pessoal'},{id:'g3',name:'Aprender algo novo',category:'mind',weekly:2,duration:30,priority:3,preferred:'evening',days:[2,5],created:today(),description:'Leitura ou estudo focado'}];s.setup=true;s.mode='demo';return s}
function loadState(){try{const st=JSON.parse(storage.getItem(KEY)||'null');if(st&&st.version===2&&st.profile&&Array.isArray(st.goals)&&Array.isArray(st.events))return st}catch(e){}return baseState()}
let S=loadState(),view='home',selected=today(),modal='',editingId=null,plannerPreview=null,weekOffset=0,filter='all',previewTab='upcoming',onboardStep=0,authClient=null,supa=null,googleToken='',googleBusy=[],cloudStatus='local',cloudTimer=null,googleLoading=false,chatBusy=false;
function save(){S.updated=today();storage.setItem(KEY,JSON.stringify(S));if(cloudStatus==='connected'){clearTimeout(cloudTimer);cloudTimer=setTimeout(saveCloud,1200)}}
function change(fn,renderAfter=true){fn(S);save();if(renderAfter)render()}
function setTheme(v){document.documentElement.dataset.theme=v;storage.setItem(themeKey,v);const tag=document.querySelector('meta[name="theme-color"]');if(tag)tag.content=v==='light'?'#f5f7fc':'#101b2e'}
setTheme(storage.getItem(themeKey)||((matchMedia('(prefers-color-scheme:light)').matches)?'light':'dark'));
const E=s=>S.events.filter(x=>x.date===s).sort((a,b)=>a.time.localeCompare(b.time));
const doneEvents=()=>S.events.filter(x=>x.status==='done');
const windowEvents=(from,to)=>S.events.filter(x=>x.date>=from&&x.date<=to);
function isToday(x){return x===today()}
function completion(){const x=windowEvents(plus(today(),-6),today());let planned=x.filter(a=>a.date<=today()&&['done','missed','skipped'].includes(a.status)).length;let complete=x.filter(a=>a.status==='done').length;return {done:complete,total:planned,rate:percent(complete,planned)}}
function streak(){let count=0;for(let i=0;i<30;i++){const dt=plus(today(),-i),events=E(dt);if(!events.some(x=>x.status==='done')){if(i===0)continue;break}count++}return count}
function currentWeek(){const st=weekStart(today());return {start:st,end:plus(st,6)}}
function statsForGoal(g,start,end){let e=S.events.filter(x=>x.goalId===g.id&&x.date>=start&&x.date<=end);let complete=e.filter(x=>x.status==='done').length;return {done:complete,target:g.weekly,planned:e.length,rate:percent(complete,g.weekly)}}
function report(){const last=plus(today(),-6);const logs=Object.entries(S.logs).filter(([dt])=>dt>=last&&dt<=today()).map(x=>x[1]);const sleep=logs.filter(x=>Number(x.sleep)>0);const energy=logs.filter(x=>Number(x.energy)>0);const all=windowEvents(last,today());return {logs,avgSleep:sleep.length?sleep.reduce((a,x)=>a+Number(x.sleep),0)/sleep.length:null,avgEnergy:energy.length?energy.reduce((a,x)=>a+Number(x.energy),0)/energy.length:null,completed:all.filter(x=>x.status==='done').length,skipped:all.filter(x=>x.status==='skipped').length,all}}
function insights(){const res=[],r=report(),todayEvents=E(today()),next=S.events.filter(x=>x.date>=today()&&x.status==='planned').length;
 if(!S.goals.length)res.push({kind:'spark',title:'Comece com uma meta possível',body:'Uma meta que cabe na semana vale mais que dez metas abandonadas. Crie seu primeiro objetivo.'});
 if(S.goals.length&&!S.events.some(x=>x.status==='planned'))res.push({kind:'calendar',title:'Seu plano ainda não foi criado',body:'Gere uma proposta de 30 dias e aprove os horários para preencher sua agenda.'});
 if(r.avgSleep!=null&&r.avgSleep<7)res.push({kind:'moon',title:'Seu sono merece espaço',body:`Você registrou média de ${r.avgSleep.toFixed(1).replace('.',',')}h de sono na última semana. Considere reduzir compromissos noturnos.`});
 if(r.skipped>=2)res.push({kind:'refresh',title:'Reorganizar pode ajudar',body:`Você marcou ${r.skipped} atividade(s) como não realizadas nos últimos sete dias. O replanejamento pode distribuir melhor as próximas sessões.`});
 if(r.avgEnergy!=null&&r.avgEnergy<=2.5)res.push({kind:'heart',title:'Menos pressão, mais recuperação',body:'Os registros recentes indicam pouca energia. Evite compensar tarefas perdidas acumulando compromissos.'});
 if(r.completed>=5)res.push({kind:'flame',title:'Uma semana de consistência',body:`Você concluiu ${r.completed} atividades nos últimos sete dias. Observe os horários que mais funcionaram.`});
 if(next&&todayEvents.length)res.push({kind:'target',title:'Hoje, o próximo passo é simples',body:`Você tem ${todayEvents.filter(x=>x.status==='planned').length} atividade(s) para confirmar hoje. O registro leva poucos segundos.`});
 if(!res.length)res.push({kind:'spark',title:'Ajuste a rota toda semana',body:'Faça check-ins reais por sete dias para receber observações personalizadas sobre sua rotina.'});
 return res.slice(0,4)}
const nav=[['home','Visão geral','home'],['goals','Minhas metas','target'],['agenda','Minha agenda','calendar'],['checkin','Registro diário','activity'],['insights','Evolução','chart'],['coach','Coach EVOLVE','spark'],['settings','Configurações','settings']];
function go(page){view=page;modal='';render();window.scrollTo({top:0,behavior:'instant'})}
function titleInfo(){return {home:['Seu espaço de evolução','Cada conquista começa com uma decisão.'],goals:['Minhas metas','Objetivos claros, uma rotina possível.'],agenda:['Minha agenda','Seus planos organizados, com espaço para viver.'],checkin:['Registro diário','O progresso real começa no que foi feito.'],insights:['Sua evolução','Dados que ajudam você a tomar melhores decisões.'],coach:['Coach EVOLVE','Um guia para refletir e ajustar sua rotina.'],settings:['Configurações','Seu tempo, seus dados, suas escolhas.']}[view]}
function header(){const [title,desc]=titleInfo();return `<div class="topbar"><div class="title-stack"><div class="eyebrow">EVOLVE / ${esc(view)}</div><h1>${title}</h1><p>${desc}</p></div><div class="top-actions"><span class="connection-pill"><span class="status-dot ${cloudStatus==='connected'?'online':''}"></span>${cloudStatus==='connected'?'Nuvem ativa':'Neste dispositivo'}</span><button class="icon-button" title="Alternar tema" data-action="theme">${ico(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-button" title="Configurações" data-nav="settings">${ico('settings')}</button></div></div>`}
function shell(content){const brand='<div class="brand"><div class="brand-mark">E</div><div><div class="brand-text">EVOLVE</div><div class="brand-sub">INTELLIGENCE ROOM</div></div></div>';return `<div class="app-shell"><aside class="sidebar">${brand}<div><div class="sidebar-label">SEU ESPAÇO</div><div class="nav-stack">${nav.map(([id,label,icon])=>`<button class="nav-btn ${view===id?'active':''}" data-nav="${id}"><span class="nav-icon">${ico(icon)}</span>${label}</button>`).join('')}</div></div><div class="sidebar-bottom"><div class="side-tip"><div class="eyebrow">UMA COISA DE CADA VEZ</div><strong>Consistência, não perfeição.</strong><p>O objetivo é viver melhor, não preencher cada minuto.</p></div><div class="mini-user"><div class="avatar">${esc((S.profile.name||'E')[0].toUpperCase())}</div><div><b>${esc(S.profile.name||'Seu espaço')}</b><small>${cloudStatus==='connected'?'Conta conectada':S.mode==='demo'?'Demonstração':'Modo local'}</small></div></div></div></aside><main class="main"><div class="main-inner">${header()}${content}</div></main><nav class="tabs-mobile" aria-label="Navegação principal">${[['home','Início','home'],['goals','Metas','target'],['agenda','Agenda','calendar'],['checkin','Diário','activity'],['insights','Evolução','chart']].map(([id,l,ic])=>`<button data-nav="${id}" class="${view===id?'active':''}" aria-label="${l}">${ico(ic)}<span>${l}</span></button>`).join('')}</nav></div>${modal?modalHtml():''}`}
function section(title,desc='',action='',label='Ver todos'){return `<div class="section-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action?`<button class="section-link" data-nav="${action}">${label} →</button>`:''}</div>`}
function stat(label,val,sub,ic){return `<div class="card stat-card"><div class="stat-kicker"><span>${label}</span><span class="mini-icon">${ico(ic)}</span></div><div class="stat-value">${val}</div><div class="stat-sub">${sub}</div></div>`}
function goalCard(g){const w=currentWeek(),r=statsForGoal(g,w.start,w.end),cat=CATS[g.category]||CATS.other;return `<article class="card goal-card"><div class="goal-top"><div class="goal-icon" aria-hidden="true">${cat.emoji}</div><button class="icon-button" style="height:31px;width:31px" title="Editar meta" data-action="edit-goal" data-id="${esc(g.id)}">${ico('edit',15)}</button></div><div><div class="goal-name">${esc(g.name)}</div><div class="goal-desc">${cat.label} · ${g.duration} min/sessão</div></div><div class="goal-metrics"><div><b>${r.done}</b><small> / ${g.weekly} esta semana</small></div><small>${r.rate}%</small></div><div class="progress-track"><div class="progress-fill" style="width:${r.rate}%"></div></div></article>`}
function taskRow(t){const g=S.goals.find(x=>x.id===t.goalId);const isDone=t.status==='done',past=t.date<today(),label=t.status==='done'?'Concluído':t.status==='skipped'?'Não realizado':t.date<today()?'Pendente':'Planejado';return `<div class="task-row"><span class="task-time">${esc(t.time)}</span><button class="check-btn ${isDone?'done':''}" aria-label="${isDone?'Desmarcar conclusão':'Concluir tarefa'}" data-action="task-toggle" data-id="${esc(t.id)}">${ico('check',16)}</button><div class="task-main"><strong>${esc(t.title)}</strong><small>${esc((g?CATS[g.category]?.label:'Evento livre')||'Planejado')} · ${t.duration} min${t.googleId?' · Google ✓':''}</small></div><span class="task-status ${isDone?'done':''}">${label}</span><button class="icon-button" style="width:29px;height:29px" title="Mais opções" data-action="edit-event" data-id="${esc(t.id)}">${ico('edit',14)}</button></div>`}
function home(){const w=currentWeek(),done=w&&windowEvents(w.start,w.end).filter(x=>x.status==='done').length,plan=windowEvents(w.start,w.end).length,rate=percent(done,plan),r=report(),name=esc((S.profile.name||'você').split(' ')[0]);const next=S.events.filter(x=>x.date>=today()&&x.status==='planned').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];return `<section class="hero"><div class="hero-text"><div class="eyebrow">SEU PRÓXIMO NÍVEL COMEÇA AQUI</div><h2>Bom te ver,<br>${name}.</h2><p>${S.goals.length?`Você tem ${S.goals.length} meta(s) em movimento. Cada pequeno passo merece ser registrado.`:'Transforme o que importa para você em uma rotina que realmente cabe na vida.'}</p><div class="hero-cta"><button class="btn primary" data-nav="checkin">${ico('check')} Registrar meu dia</button><button class="btn ghost" data-nav="agenda">${ico('calendar')} Ver agenda</button></div></div><div class="hero-orbit" style="--progress:${rate}%"><div class="orbit-text"><b>${rate}%</b><span>da semana</span></div></div></section><div class="grid four" style="margin-top:17px">${stat('Metas ativas',S.goals.length,'O que move sua evolução','target')}${stat('Sessões concluídas',done,`${plan} planejada(s) nesta semana`,'check')}${stat('Sequência',streak()+'d','Dias com atividades concluídas','flame')}${stat('Energia média',r.avgEnergy?`${r.avgEnergy.toFixed(1).replace('.',',')}/5`:'—','Últimos 7 dias','heart')}</div>${section('Suas prioridades','Progresso das metas nesta semana','goals','Gerenciar metas')}${S.goals.length?`<div class="grid three">${S.goals.slice(0,6).map(goalCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">🎯</div><strong>Seu primeiro objetivo está esperando</strong><p>Cadastre uma meta e transforme a intenção em blocos reais de tempo.</p><button class="btn primary" data-action="new-goal">${ico('plus')} Criar meta</button></div>`}<div class="grid two" style="margin-top:5px"><div>${section('Seu próximo passo','Atividades programadas para hoje','agenda','Abrir agenda')}${E(today()).length?`<div class="list-stack">${E(today()).slice(0,5).map(taskRow).join('')}</div>`:`<div class="empty"><div class="empty-icon">☀️</div><strong>Nenhuma atividade hoje</strong><p>Você pode aproveitar a pausa ou planejar algo importante.</p><button class="btn small" data-action="new-event">Adicionar atividade</button></div>`}${next&&next.date!==today()?`<p class="hint">Próximo compromisso: ${esc(next.title)}, ${formatDate(next.date)} às ${next.time}.</p>`:''}</div><div>${section('Insights do EVOLVE','Feedback baseado em registros reais','insights','Ver análise')}<div class="list-stack">${insights().slice(0,3).map(x=>feedbackHtml(x)).join('')}</div></div></div><div class="callout" style="margin-top:25px"><strong>Pronto para organizar sua próxima semana?</strong> O EVOLVE sugere horários respeitando trabalho, deslocamento, metas e intervalos. <button class="section-link" data-action="generate-plan">Criar proposta →</button></div>`}
function feedbackHtml(x){return `<div class="feedback"><div class="feedback-icon">${ico(x.kind||'spark')}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p></div></div>`}
function goals(){return `<div class="toolbar"><div><span class="tag accent">${S.goals.length} meta(s) ativa(s)</span></div><button class="btn primary" data-action="new-goal">${ico('plus')} Nova meta</button></div>${section('Seus objetivos','Metas semanais realistas e personalizáveis')}${S.goals.length?`<div class="grid three">${S.goals.map(goalCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">🎯</div><strong>Defina sua primeira meta</strong><p>Exemplo: fazer exercício três vezes por semana, estudar duas horas ou dedicar tempo a um projeto.</p><button class="btn primary" data-action="new-goal">Criar minha meta</button></div>`}<div class="card" style="margin-top:20px"><div class="toolbar"><div><strong>Transformar metas em agenda</strong><p class="hint">Gere uma proposta para as próximas quatro semanas, com intervalos e respeito aos horários de trabalho.</p></div><button class="btn primary" data-action="generate-plan">${ico('spark')} Montar rotina</button></div></div>`}
function agenda(){const w=weekStart(selected),end=plus(w,6);const events=S.events.filter(x=>x.date>=w&&x.date<=end).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="toolbar"><div class="week-nav"><button data-action="week-prev" aria-label="Semana anterior">${ico('left')}</button><span class="tag">${formatDate(w)} – ${formatDate(end)}</span><button data-action="week-next" aria-label="Próxima semana">${ico('right')}</button></div><div class="top-actions"><button class="btn ghost small" data-action="export-ics">${ico('download')} Calendário Apple (.ics)</button><button class="btn primary small" data-action="new-event">${ico('plus')} Atividade</button></div></div><div class="scroll-x" style="margin-top:16px"><div class="week-strip">${Array.from({length:7},(_,i)=>{const dt=plus(w,i),n=E(dt).length;return `<button class="day-pill ${selected===dt?'selected':''} ${today()===dt?'today':''}" data-day="${dt}">${DOW[fromKey(dt).getDay()]}<b>${fromKey(dt).getDate()}</b><small>${n?`${n} atividades`:'Livre'}</small></button>`}).join('')}</div></div><div class="grid two" style="margin-top:19px;align-items:start"><div><div class="card"><div class="toolbar"><div><div class="eyebrow">${DOW_LONG[fromKey(selected).getDay()]}</div><h2 style="font-size:20px;margin:5px 0">${formatDate(selected,true)}</h2></div><span class="tag accent">${E(selected).length} atividade(s)</span></div><div class="divider"></div>${E(selected).length?`<div class="list-stack">${E(selected).map(taskRow).join('')}</div>`:`<div class="empty"><strong>Dia sem eventos do EVOLVE</strong><p>Descanse ou adicione uma atividade manual.</p></div>`}</div><div class="card" style="margin-top:13px"><strong>Agenda e privacidade</strong><p class="hint">Eventos locais são privados ao navegador. Exportar .ics permite importar no Calendário do iPhone; não é uma sincronização bidirecional.</p><div class="toolbar"><button class="btn small ghost" data-action="generate-plan">Gerar rotina</button><button class="btn small ghost" data-nav="settings">Conectar Google</button></div></div></div><div class="card"><div class="eyebrow">RESUMO DA SEMANA</div><h2 style="font-size:21px;margin:9px 0 17px">${events.length} atividades planejadas</h2><div class="list-stack">${events.length?events.map(e=>`<div class="task-row"><span class="task-time">${DOW[fromKey(e.date).getDay()]}</span><div class="task-main"><strong>${esc(e.title)}</strong><small>${e.time} · ${e.duration} min</small></div><span class="task-status ${e.status==='done'?'done':''}">${e.status==='done'?'Feito':e.status==='skipped'?'Pulou':'Agendado'}</span></div>`).join(''):`<p class="muted tiny">Ainda não há compromissos nesta semana.</p>`}</div><div class="divider"></div><button class="btn primary full" data-action="sync-google">${ico('calendar')} Enviar para Google Calendar</button><p class="hint">Somente após autorização e confirmação. Nenhum evento é enviado automaticamente.</p></div></div>`}
function checkin(){const log=S.logs[selected]||{},date=selected,events=E(date),navD=`<div class="week-nav"><button data-action="day-prev">${ico('left')}</button><span class="tag">${formatDate(date,true)}</span><button data-action="day-next">${ico('right')}</button></div>`;return `<div class="toolbar">${navD}<span class="tag">Seu momento de reflexão</span></div><div class="grid two" style="margin-top:19px;align-items:start"><div class="card"><div class="eyebrow">O QUE VOCÊ REALIZOU</div><h2 style="margin:7px 0 17px;font-size:21px">Atividades do dia</h2>${events.length?`<div class="list-stack">${events.map(taskRow).join('')}</div>`:`<div class="empty"><strong>Sem atividades programadas</strong><p>Você pode adicionar um compromisso ou apenas registrar como se sentiu.</p><button class="btn small" data-action="new-event">Adicionar</button></div>`}</div><div class="card"><div class="eyebrow">COMO FOI SEU DIA?</div><h2 style="margin:7px 0 17px;font-size:21px">Seu check-in</h2><form id="checkin-form" class="list-stack"><div class="form-grid"><div class="field"><label for="sleep">Sono (horas)</label><input id="sleep" name="sleep" type="number" step="0.5" min="0" max="16" value="${esc(log.sleep||'')}" placeholder="Ex.: 7.5"></div><div class="field"><label for="energy">Energia (1–5)</label><select id="energy" name="energy"><option value="">Selecionar</option>${[1,2,3,4,5].map(i=>`<option ${Number(log.energy)===i?'selected':''} value="${i}">${i} · ${['','Muito baixa','Baixa','Regular','Boa','Excelente'][i]}</option>`).join('')}</select></div><div class="field"><label for="water">Água (copos)</label><input id="water" name="water" type="number" min="0" max="30" value="${esc(log.water??'')}" placeholder="Ex.: 6"></div><div class="field"><label for="meals">Refeições caseiras</label><input id="meals" name="meals" type="number" min="0" max="10" value="${esc(log.meals??'')}" placeholder="Ex.: 2"></div></div><div class="field"><label for="mood">Humor</label><select id="mood" name="mood"><option value="">Selecionar</option>${['Muito difícil','Difícil','Neutro','Bom','Excelente'].map((v,i)=>`<option value="${i+1}" ${Number(log.mood)===i+1?'selected':''}>${['','😣','😕','😐','🙂','😁'][i+1]} ${v}</option>`).join('')}</select></div><div class="field"><label for="notes">Reflexão do dia</label><textarea id="notes" name="notes" maxlength="1500" placeholder="O que funcionou? O que poderia ser mais leve amanhã?">${esc(log.notes||'')}</textarea></div><button class="btn primary full" type="submit">${ico('check')} Salvar check-in</button></form></div></div>`}
function insightsPage(){const r=report(),w=currentWeek();const last7=Array.from({length:7},(_,i)=>plus(today(),i-6));const bars=last7.map(dt=>{let n=E(dt).filter(x=>x.status==='done').length;return {day:DOW[fromKey(dt).getDay()],n}});const max=Math.max(1,...bars.map(x=>x.n));return `<div class="grid four">${stat('Conclusões 7 dias',r.completed,'Atividades efetivamente feitas','check')}${stat('Energia média',r.avgEnergy?r.avgEnergy.toFixed(1).replace('.',',')+'/5':'—','Registros desta semana','heart')}${stat('Sono médio',r.avgSleep?r.avgSleep.toFixed(1).replace('.',',')+'h':'—','Baseado nos seus check-ins','moon')}${stat('Dias registrados',r.logs.length,'Dos últimos sete dias','book')}</div><div class="grid two" style="margin-top:17px;align-items:start"><div class="card"><div class="toolbar"><div><h2 style="font-size:18px;margin:0">Atividades concluídas</h2><p class="hint">Comparação dos últimos sete dias</p></div><span class="tag">7 dias</span></div><div class="bar-chart">${bars.map(x=>`<div class="bar-slot"><div class="tip">${x.n}</div><div class="bar ${x.n?'':'dim'}" style="height:${x.n?Math.max(10,Math.round(x.n/max*115)):5}px"></div><label>${x.day}</label></div>`).join('')}</div></div><div class="card"><div class="eyebrow">SEU BALANÇO SEMANAL</div><h2 style="font-size:18px;margin:10px 0">Metas e progresso</h2><div class="list-stack">${S.goals.length?S.goals.map(g=>{let a=statsForGoal(g,w.start,w.end);return `<div><div class="toolbar"><strong class="tiny">${esc(g.name)}</strong><small class="muted">${a.done} / ${a.target}</small></div><div class="progress-track" style="margin-top:7px"><div class="progress-fill" style="width:${a.rate}%"></div></div></div>`}).join(''):'<p class="muted tiny">Cadastre metas para visualizar progresso por objetivo.</p>'}</div></div></div>${section('Feedbacks inteligentes','Insights extraídos das suas atividades e check-ins')}<div class="grid two">${insights().map(feedbackHtml).join('')}</div>${section('Revisão semanal','O que deu certo? O que deve mudar?')}<div class="card"><form id="review-form" class="form-grid"><div class="field"><label>Principal conquista</label><textarea name="wins" maxlength="1500" placeholder="Um avanço do qual me orgulho...">${esc((S.reviews.find(x=>x.week===w.start)||{}).wins||'')}</textarea></div><div class="field"><label>Obstáculo mais importante</label><textarea name="obstacles" maxlength="1500" placeholder="O que dificultou minha rotina...">${esc((S.reviews.find(x=>x.week===w.start)||{}).obstacles||'')}</textarea></div><div class="field" style="grid-column:1/-1"><label>Ajuste para a próxima semana</label><textarea name="adjust" maxlength="1500" placeholder="Uma mudança pequena e concreta...">${esc((S.reviews.find(x=>x.week===w.start)||{}).adjust||'')}</textarea></div><div class="form-actions" style="grid-column:1/-1"><button class="btn ghost" type="button" data-action="share-summary">${ico('share')} Compartilhar resumo</button><button type="submit" class="btn primary">${ico('check')} Salvar revisão</button></div></form></div>`}
function coachPage(){return `<div class="grid two" style="align-items:start"><div class="card"><div class="eyebrow">REFLEXÃO GUIADA</div><h2 style="font-size:22px;margin:8px 0 5px">Seu coach de rotina</h2><p class="hint">Respostas baseadas nas metas e registros locais. IA avançada é opcional e exige configuração segura do servidor.</p><div class="chat-space" id="chat-space">${S.chat.length?S.chat.slice(-22).map(x=>`<div class="bubble ${x.role==='user'?'me':'bot'}">${esc(x.text)}</div>`).join(''):`<div class="bubble bot">Olá! Vamos melhorar sua rotina com dados reais. Você pode perguntar sobre consistência, energia, planejamento ou prioridades.</div>`}</div><form id="chat-form" class="chat-input"><input name="message" maxlength="800" autocomplete="off" required placeholder="Ex.: Como melhorar minha semana?"><button class="btn primary" type="submit" ${chatBusy?'disabled':''}>${ico('arrow')}</button></form></div><div><div class="card"><div class="eyebrow">PERGUNTAS SUGERIDAS</div><div class="list-stack" style="margin-top:14px">${['O que devo priorizar agora?','Como está minha consistência?','Como posso melhorar minha energia?','Sugira um ajuste para a semana'].map(s=>`<button class="btn ghost" data-coach="${esc(s)}" style="justify-content:space-between;text-align:left">${esc(s)} ${ico('arrow')}</button>`).join('')}</div></div><div class="card" style="margin-top:13px"><div class="eyebrow">FEEDBACK ATUAL</div><div class="list-stack" style="margin-top:12px">${insights().map(feedbackHtml).join('')}</div><button class="btn ghost full" style="margin-top:15px" data-action="replan">${ico('refresh')} Replanejar pendências</button></div></div></div>`}
function settings(){const p=S.profile;return `<div class="grid two" style="align-items:start"><div><div class="card"><div class="eyebrow">PERFIL E DISPONIBILIDADE</div><h2 style="font-size:19px;margin:9px 0 17px">Sua rotina-base</h2><form id="profile-form" class="list-stack"><div class="field"><label>Como devemos te chamar?</label><input name="name" maxlength="55" required value="${esc(p.name)}" placeholder="Seu nome"></div><div class="form-grid"><div class="field"><label>Acordar</label><input type="time" name="wake" value="${esc(p.wake)}"></div><div class="field"><label>Dormir</label><input type="time" name="sleep" value="${esc(p.sleep)}"></div><div class="field"><label>Trabalho: início</label><input type="time" name="workStart" value="${esc(p.workStart)}"></div><div class="field"><label>Trabalho: fim</label><input type="time" name="workEnd" value="${esc(p.workEnd)}"></div></div><div class="field"><label>Deslocamento por trecho (min)</label><input type="number" name="commute" min="0" max="240" value="${Number(p.commute)||0}"></div><div class="field"><span class="field-label">Dias de escritório</span><div class="chip-group">${[1,2,3,4,5].map(i=>`<button type="button" class="chip ${p.officeDays.includes(i)?'selected':''}" data-action="office-day" data-daynum="${i}">${DOW[i]}</button>`).join('')}</div><small>Incluiremos deslocamento e bloqueio de trabalho no planejamento.</small></div><button class="btn primary full" type="submit">${ico('check')} Salvar preferências</button></form></div><div class="card" style="margin-top:15px"><div class="eyebrow">APARÊNCIA E DADOS</div><div class="setting-row"><div><strong>Tema do aplicativo</strong><small>Personalize o visual no seu dispositivo.</small></div><button class="btn ghost small" data-action="theme">${document.documentElement.dataset.theme==='dark'?'Modo escuro':'Modo claro'}</button></div><div class="setting-row"><div><strong>Exportar meu histórico</strong><small>Backup completo das suas metas e registros.</small></div><button class="btn small ghost" data-action="backup">${ico('download')} JSON</button></div><div class="setting-row"><div><strong>Importar backup</strong><small>Substitui os dados deste espaço após confirmação.</small></div><button class="btn small ghost" data-action="import-backup">${ico('upload')} Importar</button></div><div class="setting-row"><div><strong>Exportar atividades</strong><small>CSV, para planilhas e relatórios.</small></div><button class="btn small ghost" data-action="export-csv">CSV</button></div><div class="setting-row"><div><strong>Apagar dados locais</strong><small>Ação irreversível sem backup.</small></div><button class="btn small danger" data-action="reset">Apagar</button></div><input type="file" id="backup-file" accept="application/json,.json" class="hidden"/></div></div><div><div class="card"><div class="eyebrow">CONTA E SINCRONIZAÇÃO</div><h2 style="font-size:19px;margin:9px 0 13px">Seus dados, sob seu controle</h2><div class="callout"><strong>${cloudStatus==='connected'?'Sua conta está conectada':'Modo local ativo'}</strong><div style="margin-top:5px">${cloudStatus==='connected'?'Seus dados são sincronizados com seu espaço na nuvem.':'Sem configuração de Supabase, cada navegador mantém seus próprios dados. Esta versão permite testar sem cadastro.'}</div></div>${C.supabaseUrl&&C.supabaseAnonKey?`<div class="form-actions">${cloudStatus==='connected'?`<button class="btn ghost" data-action="logout">${ico('logout')} Sair da conta</button>`:`<button class="btn primary" data-action="login">${ico('user')} Entrar com e-mail</button>`}</div>`:`<p class="hint">Cadastro multiusuário será habilitado quando o administrador adicionar Supabase URL e chave publicável em config.js e executar as políticas RLS.</p>`}<div class="divider"></div><div class="eyebrow">GOOGLE CALENDAR</div><p class="hint">Consulta de agenda e criação de eventos com autorização explícita. Não sincronizamos em segundo plano nesta versão.</p>${C.googleClientId?`<div class="toolbar"><span class="tag ${googleToken?'accent':''}">${googleToken?'Autorizado nesta sessão':'Não conectado'}</span><button class="btn small primary" data-action="google-auth">${ico('calendar')} ${googleToken?'Renovar acesso':'Conectar Google'}</button></div><div class="form-actions"><button class="btn ghost" data-action="google-busy">Ler horários ocupados</button><button class="btn primary" data-action="sync-google">Enviar eventos</button></div>`:`<div class="callout"><strong>Integração aguardando credencial.</strong> O administrador precisa configurar um OAuth Client ID Google autorizado para esta origem.</div>`}</div><div class="card" style="margin-top:15px"><div class="eyebrow">IPHONE E COMPARTILHAMENTO</div><div class="setting-row"><div><strong>Calendário Apple</strong><small>Exportação .ics compatível com importação manual.</small></div><button class="btn small ghost" data-action="export-ics">${ico('download')} .ics</button></div><div class="setting-row"><div><strong>Compartilhar progresso</strong><small>Resumo de texto, sem dados sensíveis automáticos.</small></div><button class="btn small ghost" data-action="share-summary">${ico('share')} Compartilhar</button></div><div class="setting-row"><div><strong>Enviar feedback da versão Beta</strong><small>Abre issue pública no GitHub. Não inclua dados privados.</small></div><button class="btn small ghost" data-action="feedback">${ico('message')} Feedback</button></div></div><div class="card" style="margin-top:15px"><div class="eyebrow">TRANSPARÊNCIA DO BETA</div><p class="hint">✓ Metas, agenda local, check-ins, progresso, replanejamento, revisão e backup funcionam sem conta.</p><p class="hint">◉ Conta real: requer configuração do Supabase.</p><p class="hint">◉ Google: requer OAuth; sincronização somente ao solicitar.</p><p class="hint">◉ Calendário iPhone: importação .ics; integração nativa bidirecional exige aplicativo iOS.</p><p class="hint">◉ IA generativa e desafios sociais em tempo real: próximos módulos; o coach atual oferece orientações baseadas em regras.</p></div></div></div>`}
function render(){const app=$('#app');if(!app)return;if(!S.setup){app.innerHTML=onboard();return}let c={home,goals,agenda,checkin,insights:insightsPage,coach:coachPage,settings}[view]();app.innerHTML=shell(c);const chat=$('#chat-space');if(chat)chat.scrollTop=chat.scrollHeight}
function onboardingBrand(){return '<div class="brand"><div class="brand-mark">E</div><div><div class="brand-text">EVOLVE</div><div class="brand-sub">BETA EXPERIENCE</div></div></div>'}
function onboard(){const steps=[`<div class="eyebrow">SUA JORNADA COMEÇA AQUI</div><h2>Mais clareza. Mais ação.</h2><p>Conte um pouco sobre você, e o EVOLVE vai transformar suas prioridades em uma rotina possível.</p><div class="onboard-card" style="margin-top:21px"><div class="field"><label>Qual é o seu nome?</label><input id="welcome-name" maxlength="55" value="${esc(S.profile.name)}" placeholder="Como quer ser chamado?"></div><div class="form-actions"><button class="btn primary" data-action="ob-next">Continuar ${ico('arrow')}</button></div></div><div class="auth-separator">ou</div><button class="btn ghost full" data-action="try-demo">${ico('spark')} Explorar demonstração</button>`,`<div class="eyebrow">SUAS PRIORIDADES</div><h2>O que realmente importa agora?</h2><p>Escolha até três áreas que você deseja colocar em movimento.</p><div class="grid two" style="margin-top:22px">${Object.entries(CATS).filter(([k])=>k!=='other').map(([k,x])=>`<button class="card ${S.profile.priorities.includes(k)?'prio-selected':''}" data-action="select-prio" data-prio="${k}" style="text-align:left;cursor:pointer;border-color:${S.profile.priorities.includes(k)?'var(--mint)':'var(--border)'}"><span style="font-size:28px">${x.emoji}</span><div style="font-weight:800;margin-top:10px">${x.label}</div></button>`).join('')}</div><div class="form-actions"><button class="btn ghost" data-action="ob-prev">Voltar</button><button class="btn primary" data-action="ob-next">Continuar ${ico('arrow')}</button></div>`,`<div class="eyebrow">TEMPO E DISPONIBILIDADE</div><h2>Vamos reservar espaço para viver.</h2><p>Usaremos estes horários para evitar sobreposição com trabalho e sono.</p><div class="form-grid" style="margin-top:22px"><div class="field"><label>Acordar</label><input id="ob-wake" type="time" value="${esc(S.profile.wake)}"></div><div class="field"><label>Dormir</label><input id="ob-sleep" type="time" value="${esc(S.profile.sleep)}"></div><div class="field"><label>Trabalho: início</label><input id="ob-workstart" type="time" value="${esc(S.profile.workStart)}"></div><div class="field"><label>Trabalho: fim</label><input id="ob-workend" type="time" value="${esc(S.profile.workEnd)}"></div><div class="field"><label>Deslocamento por trecho (min)</label><input id="ob-commute" type="number" min="0" max="240" value="${esc(S.profile.commute)}"></div></div><div class="form-actions"><button class="btn ghost" data-action="ob-prev">Voltar</button><button class="btn primary" data-action="finish-ob">Criar meu espaço ${ico('arrow')}</button></div>`];return `<div class="onboard-screen"><div class="onboard-left">${onboardingBrand()}<div><div class="eyebrow" style="color:#a2f6dd">SEU TEMPO TEM VALOR</div><h1>Uma vida melhor, <span style="color:#95efd8">um dia por vez.</span></h1><p>Metas, agenda, registros e feedbacks. Tudo conectado ao que faz sentido para você.</p></div><div class="welcome-decor"><span><b>01</b>Defina</span><span><b>02</b>Planeje</span><span><b>03</b>Evolua</span></div></div><div class="onboard-right"><div class="onboard-progress">${[0,1,2].map(i=>`<span class="${onboardStep>=i?'on':''}"></span>`).join('')}</div>${steps[onboardStep]}</div></div>`}
function modalHtml(){let content='',heading='';if(modal==='goal'){const g=S.goals.find(x=>x.id===editingId)||{name:'',category:S.profile.priorities[0]||'health',description:'',weekly:3,duration:30,priority:2,preferred:'flex',days:[1,2,3,4,5]};heading=editingId?'Editar meta':'Nova meta';content=`<form id="goal-form" class="list-stack"><div class="field"><label>Nome da meta</label><input name="name" required maxlength="80" value="${esc(g.name)}" placeholder="Ex.: Treinar 3 vezes por semana"></div><div class="field"><label>Área da vida</label><select name="category">${Object.entries(CATS).map(([k,v])=>`<option value="${k}" ${k===g.category?'selected':''}>${v.emoji} ${v.label}</option>`).join('')}</select></div><div class="field"><label>Por que essa meta importa? (opcional)</label><textarea name="description" maxlength="260" placeholder="Sua motivação...">${esc(g.description||'')}</textarea></div><div class="form-grid"><div class="field"><label>Sessões por semana</label><input name="weekly" type="number" min="1" max="7" required value="${g.weekly}"></div><div class="field"><label>Minutos por sessão</label><input name="duration" type="number" min="10" max="240" step="5" required value="${g.duration}"></div><div class="field"><label>Melhor horário</label><select name="preferred"><option value="flex" ${g.preferred==='flex'?'selected':''}>Qualquer horário livre</option><option value="morning" ${g.preferred==='morning'?'selected':''}>Manhã</option><option value="evening" ${g.preferred==='evening'?'selected':''}>Noite</option></select></div><div class="field"><label>Prioridade</label><select name="priority"><option value="1" ${Number(g.priority)===1?'selected':''}>Alta</option><option value="2" ${Number(g.priority)===2?'selected':''}>Média</option><option value="3" ${Number(g.priority)===3?'selected':''}>Flexível</option></select></div></div><div class="field"><span class="field-label">Dias em que pode fazer</span><div class="chip-group">${[1,2,3,4,5,6,0].map(i=>`<button type="button" data-action="goal-day" data-daynum="${i}" class="chip ${g.days.includes(i)?'selected':''}">${DOW[i]}</button>`).join('')}</div></div><div class="form-actions">${editingId?`<button type="button" class="btn danger" data-action="delete-goal" data-id="${esc(editingId)}">Excluir meta</button>`:''}<button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${ico('check')} Salvar meta</button></div></form>`}
else if(modal==='event'){const ev=S.events.find(x=>x.id===editingId)||{title:'',date:selected,time:'19:00',duration:30,goalId:'',status:'planned'};heading=editingId?'Editar atividade':'Adicionar atividade';content=`<form id="event-form" class="list-stack"><div class="field"><label>Atividade</label><input name="title" required maxlength="110" value="${esc(ev.title)}" placeholder="Ex.: Caminhada no parque"></div><div class="form-grid"><div class="field"><label>Data</label><input name="date" type="date" required value="${esc(ev.date)}"></div><div class="field"><label>Horário</label><input name="time" type="time" required value="${esc(ev.time)}"></div><div class="field"><label>Duração (min)</label><input name="duration" type="number" min="10" max="360" step="5" required value="${ev.duration}"></div><div class="field"><label>Meta vinculada</label><select name="goalId"><option value="">Sem meta</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${ev.goalId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div></div><div class="form-actions">${editingId?`<button class="btn danger" type="button" data-action="delete-event" data-id="${esc(editingId)}">Excluir</button><button class="btn ghost" type="button" data-action="skip-event" data-id="${esc(editingId)}">Não fiz</button>`:''}<button class="btn primary" type="submit">Salvar atividade</button></div></form>`}
else if(modal==='plan'){heading='Sua nova rotina';const p=plannerPreview||{events:[],warnings:[]};content=`<div class="callout"><strong>Planejamento proposto — próximos 28 dias</strong><div style="margin-top:4px">${p.events.length} sessão(ões) distribuída(s), respeitando trabalho, deslocamentos, atividades existentes e tempo entre compromissos. Revise antes de aplicar.</div></div>${p.warnings.length?`<div class="feedback" style="margin:12px 0"><div class="feedback-icon">${ico('bell')}</div><div><strong>Nem tudo coube</strong><p>${esc(p.warnings.slice(0,5).join(' • '))}</p></div></div>`:''}<div class="list-stack" style="margin:17px 0;max-height:335px;overflow-y:auto">${p.events.slice(0,28).map(t=>`<div class="task-row"><span class="task-time">${formatDate(t.date)}</span><div class="task-main"><strong>${esc(t.title)}</strong><small>${t.time} · ${t.duration} min</small></div></div>`).join('')}${p.events.length>28?`<p class="hint">E mais ${p.events.length-28} atividades nas próximas semanas.</p>`:''}</div><div class="form-actions"><button class="btn ghost" data-action="close-modal">Cancelar</button><button class="btn primary" data-action="apply-plan" ${!p.events.length?'disabled':''}>${ico('check')} Aplicar meu plano</button></div><p class="hint">Atividades anteriores concluídas serão preservadas. Eventos futuros gerados automaticamente serão substituídos após confirmação.</p>`}
else if(modal==='login'){heading='Entrar no EVOLVE';content=`<div class="callout"><strong>Conta por link de acesso</strong><p style="margin:6px 0 0">Enviaremos um link por e-mail. Não precisa criar senha. O administrador deve configurar Supabase para este recurso funcionar.</p></div><form id="login-form" class="list-stack" style="margin-top:16px"><div class="field"><label>Seu e-mail</label><input name="email" type="email" autocomplete="email" required placeholder="voce@exemplo.com"></div><button class="btn primary full" type="submit">Enviar link de acesso</button></form>`}
else if(modal==='feedback'){heading='Feedback do teste beta';content=`<p class="hint">O reporte será aberto em uma issue pública no GitHub. Evite compartilhar dados de saúde, registros pessoais ou informações confidenciais.</p><form id="feedback-form" class="list-stack"><div class="field"><label>Como foi sua experiência?</label><select name="rating"><option value="5">★★★★★ · Excelente</option><option value="4">★★★★ · Boa</option><option value="3">★★★ · Regular</option><option value="2">★★ · Precisa melhorar</option><option value="1">★ · Ruim</option></select></div><div class="field"><label>O que devemos melhorar?</label><textarea name="message" required maxlength="1000" placeholder="Descreva erro, sugestão ou dificuldade..."></textarea></div><button class="btn primary full" type="submit">Abrir feedback público no GitHub</button></form>`}
return `<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><header><h2>${heading}</h2><button aria-label="Fechar" data-action="close-modal">${ico('close')}</button></header>${content}</section></div>`}
function openModal(m,id=null){modal=m;editingId=id;render()}
function finishOnboarding(){S.profile.wake=$('#ob-wake').value;S.profile.sleep=$('#ob-sleep').value;S.profile.workStart=$('#ob-workstart').value;S.profile.workEnd=$('#ob-workend').value;S.profile.commute=clamp(safeNum($('#ob-commute'),50),0,240);S.setup=true;S.mode='local';save();render();notify('Seu espaço está pronto. Cadastre sua primeira meta!')}
function goalForm(fd){const g={id:editingId||uuid(),name:String(fd.get('name')).trim().slice(0,80),category:fd.get('category'),description:String(fd.get('description')||'').trim().slice(0,260),weekly:clamp(Number(fd.get('weekly'))||1,1,7),duration:clamp(Number(fd.get('duration'))||30,10,240),priority:clamp(Number(fd.get('priority'))||2,1,3),preferred:fd.get('preferred'),days:$$('[data-action="goal-day"].selected').map(x=>Number(x.dataset.daynum)),created:today()};if(!g.days.length){notify('Escolha ao menos um dia possível para a meta.');return}if(g.weekly>g.days.length){notify('A frequência não pode superar o número de dias disponíveis.');return}change(s=>{const idx=s.goals.findIndex(x=>x.id===g.id);if(idx>=0)s.goals[idx]=g;else s.goals.push(g)});modal='';render();notify('Meta salva! Gere sua rotina para distribuir as sessões.')}
function eventForm(fd){const e={id:editingId||uuid(),title:String(fd.get('title')||'').trim().slice(0,110),date:String(fd.get('date')),time:String(fd.get('time')),duration:clamp(Number(fd.get('duration'))||30,10,360),goalId:String(fd.get('goalId')||''),status:'planned',source:'manual',googleId:null};if(!e.title||!e.date||!e.time)return notify('Preencha os campos obrigatórios.');const start=minutes(e.time),stop=start+e.duration;if(stop>1440)return notify('A atividade ultrapassa o fim do dia.');if(hasConflict(e.date,start,stop,editingId)){if(!confirm('Este horário se sobrepõe a outro compromisso do EVOLVE ou ao seu trabalho. Deseja salvar mesmo assim?'))return}change(s=>{const idx=s.events.findIndex(x=>x.id===e.id);if(idx>=0){e.status=s.events[idx].status;e.googleId=null;s.events[idx]=e}else s.events.push(e)});modal='';render();notify('Atividade adicionada.')}
function busyFor(date,ignoreId){const d=fromKey(date).getDay(),p=S.profile,arr=[];if(d>=1&&d<=5){const workStart=minutes(p.workStart),workEnd=minutes(p.workEnd);if(workStart<workEnd){arr.push([workStart,workEnd,'trabalho']);if((p.officeDays||[]).includes(d)){const commute=clamp(Number(p.commute)||0,0,240);arr.push([workStart-commute,workStart,'deslocamento'],[workEnd,workEnd+commute,'deslocamento'])}}}
 for(const e of S.events){if(e.date===date&&e.id!==ignoreId&&e.status!=='skipped')arr.push([minutes(e.time),minutes(e.time)+e.duration,e.title]);}
 for(const e of googleBusy){if(e.date===date)arr.push([minutes(e.time),minutes(e.time)+e.duration,'agenda Google']);}
 return arr}
function hasConflict(dt,start,end,ignoreId=null,buffer=0){return busyFor(dt,ignoreId).some(([a,b])=>start<b+buffer&&end>a-buffer)}
function getAvailableTimes(dt,g){let p=S.profile,d=fromKey(dt).getDay(),office=(p.officeDays||[]).includes(d);const slots=[];let wake=minutes(p.wake),sleep=minutes(p.sleep);if(sleep<=wake)sleep+=1440;const base=[[Math.max(wake+10,360),Math.min(540,sleep-25)],[Math.max(1080,minutes(p.workEnd)+(office?Number(p.commute)||0:0)+20),Math.min(1350,sleep-30)]];
 if(d===0||d===6)base.push([Math.max(wake+30,480),Math.min(1230,sleep-30)]);
 if(g.preferred==='morning')base.sort((a,b)=>a[0]-b[0]);else if(g.preferred==='evening')base.sort((a,b)=>b[0]-a[0]);
 let seen=new Set();for(const [start,end] of base){for(let time=Math.ceil(start/15)*15;time+g.duration<=end;time+=15){if(time+g.duration>1440||seen.has(time))continue;seen.add(time);if(!hasConflict(dt,time,time+g.duration,null,10))slots.push({time,score:Math.abs(time-(g.preferred==='morning'?465:g.preferred==='evening'?1170:1050))})}}
 return slots.sort((a,b)=>a.score-b.score)}
function generatePlan(){const start=today(),end=plus(start,27),original=S.events;const gSorted=[...S.goals].sort((a,b)=>a.priority-b.priority);const existing=original.filter(e=>e.date>=start&&e.date<=end&&(e.source!=='generated'||e.status==='done'));const backup=S.events;const generated=[],warnings=[];
 S.events=existing;for(let i=0;i<4;i++){const ws=plus(start,i*7);for(const g of gSorted){let count=0;const allowed=Array.from({length:7},(_,j)=>plus(ws,j)).filter(dt=>(g.days||[1,2,3,4,5]).includes(fromKey(dt).getDay()));const preferred=[...allowed].sort((a,b)=>{const ia=daysBetween(ws,a),ib=daysBetween(ws,b);return Math.abs(ia-((count+.5)*7/g.weekly)) - Math.abs(ib-((count+.5)*7/g.weekly))});
 const taken=new Set();while(count<g.weekly){const choices=allowed.filter(dt=>!taken.has(dt)).map(dt=>({dt,times:getAvailableTimes(dt,g)})).filter(x=>x.times.length);if(!choices.length)break;const ideal=(count+.5)*7/g.weekly;choices.sort((a,b)=>Math.abs(daysBetween(ws,a.dt)-ideal)-Math.abs(daysBetween(ws,b.dt)-ideal)||a.times[0].score-b.times[0].score);const c=choices[0];const task={id:uuid(),title:g.name,date:c.dt,time:clock(c.times[0].time),duration:g.duration,goalId:g.id,status:'planned',source:'generated',googleId:null};generated.push(task);S.events.push(task);taken.add(c.dt);count++}
 if(count<g.weekly)warnings.push(`${g.name}: ${count}/${g.weekly} sessões na semana ${i+1}`)}}S.events=backup;plannerPreview={events:generated,warnings};openModal('plan')}
function applyPlan(){if(!plannerPreview)return;const now=today();change(s=>{s.events=s.events.filter(e=>e.date<now||e.source!=='generated'||e.status==='done');s.events.push(...plannerPreview.events)});plannerPreview=null;modal='';render();notify('Rotina de 28 dias aplicada ao EVOLVE. Para Google, confirme envio na agenda.')}
function replan(){let skipped=S.events.filter(x=>x.date<=today()&&(x.status==='skipped'||(x.status==='planned'&&x.date<today())));if(!skipped.length){notify('Não há pendências registradas para replanejar.');return}let created=0;change(s=>{for(const event of skipped.slice(0,15)){if(!event.goalId)continue;const goal=s.goals.find(g=>g.id===event.goalId);if(!goal)continue;for(let i=1;i<=14;i++){let dt=plus(today(),i);if(!(goal.days||[]).includes(fromKey(dt).getDay()))continue;const options=getAvailableTimes(dt,goal);if(options.length){s.events.push({...event,id:uuid(),date:dt,time:clock(options[0].time),status:'planned',googleId:null,source:'generated'});event.status='skipped';created++;break}}}});notify(created?`${created} atividade(s) reagendada(s) nas próximas duas semanas.`:'Não foi possível encontrar horários livres. Revise as metas e a disponibilidade.')}
function calendarDate(e){const [h,m]=e.time.split(':').map(Number);const d=fromKey(e.date);d.setHours(h,m,0,0);return d}
function icsEscape(s){return String(s||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/[;,]/g,x=>'\\'+x)}
function icsDate(d){return d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}
function exportICS(){if(!S.events.length)return notify('Ainda não há atividades para exportar.');const a=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//EVOLVE//Beta//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const e of S.events.filter(x=>x.status!=='skipped')){const start=calendarDate(e),end=new Date(start.getTime()+e.duration*60000);a.push('BEGIN:VEVENT',`UID:${e.id}@evolve.app`,`DTSTAMP:${icsDate(new Date())}`,`DTSTART:${icsDate(start)}`,`DTEND:${icsDate(end)}`,`SUMMARY:${icsEscape(e.title)}`,`DESCRIPTION:${icsEscape('Criado pelo EVOLVE. Status: '+(e.status==='done'?'concluído':'planejado'))}`,'END:VEVENT')}a.push('END:VCALENDAR');download('EVOLVE-minha-agenda.ics',a.join('\r\n'),'text/calendar;charset=utf-8');notify('Arquivo .ics gerado. Importe no Calendário Apple quando desejar.')}
function backup(){download(`EVOLVE-backup-${today()}.json`,JSON.stringify({app:'evolve-beta',exportedAt:new Date().toISOString(),state:S},null,2),'application/json');notify('Backup JSON exportado.')}
function exportCSV(){const head=['Data','Horário','Atividade','Meta','Duração (min)','Status','Fonte'];const arr=[head,...S.events.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>[e.date,e.time,e.title,S.goals.find(g=>g.id===e.goalId)?.name||'',e.duration,e.status,e.source])];download(`EVOLVE-atividades-${today()}.csv`,'\ufeff'+arr.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');notify('CSV exportado.')}
async function shareSummary(){const r=report(),t=`Meu progresso EVOLVE 🌱\nÚltimos 7 dias: ${r.completed} atividades concluídas; ${S.goals.length} metas ativas.\nConsistência é progresso.\nExperimente: ${location.href.split('#')[0]}`;try{if(navigator.share)await navigator.share({title:'Meu EVOLVE',text:t});else{await navigator.clipboard.writeText(t);notify('Resumo copiado para compartilhar!')}}catch(e){if(e.name!=='AbortError')notify('Compartilhamento indisponível.') }}
function coachAnswer(q){const x=q.toLowerCase(),r=report(),missing=S.events.filter(e=>e.date<today()&&e.status==='planned').length,top=S.goals.slice().sort((a,b)=>a.priority-b.priority)[0];if(/energia|cansa|sono|dormi/.test(x))return `Na última semana, ${r.avgSleep!=null?`seu sono médio registrado foi ${r.avgSleep.toFixed(1).replace('.',',')}h`:'ainda faltam registros de sono'} e ${r.avgEnergy!=null?`a energia média foi ${r.avgEnergy.toFixed(1).replace('.',',')}/5`:'a energia não foi registrada'}. Priorize intervalos e descanso; reduza intensidade se a recuperação estiver ruim.`;if(/consist|progres|desempenho|resultado/.test(x))return `Você concluiu ${r.completed} atividade(s) nos últimos sete dias e registrou ${r.logs.length} check-in(s). ${r.completed?`Identifique qual período funcionou melhor e repita esse padrão.`:'Comece marcando uma sessão concluída de cada vez; não é preciso recuperar tudo.'}`;if(/planej|agenda|ajust|próxim|semana|reorganiz/.test(x))return `Seu plano tem ${missing} compromisso(s) passado(s) ainda pendentes. Sugiro selecionar até três metas prioritárias, manter 10 minutos entre atividades e reservar tempo de recuperação. Use “Replanejar pendências” para criar novas sugestões — nada é enviado ao Google sem sua aprovação.`;if(/prior|foco|importa/.test(x))return top?`Sua meta de prioridade mais alta é “${top.name}”. Ela pede ${top.weekly} sessão(ões) de ${top.duration} minutos por semana. Comece encaixando uma sessão simples e proteja esse horário.`:'Sua primeira prioridade é definir uma meta específica, realista e com duração semanal possível.';return `Vamos olhar para o que você controla: ${r.completed} atividade(s) concluída(s) na última semana e ${S.goals.length} meta(s) ativa(s). Escolha uma ação pequena para amanhã, deixe folga na agenda e registre o resultado. Se quiser, pergunte sobre foco, sono, consistência ou replanejamento.`}
async function askCoach(q){if(!q||chatBusy)return;change(s=>s.chat.push({role:'user',text:q,at:Date.now()}),false);chatBusy=true;render();let answer='';try{if(supa&&cloudStatus==='connected'&&C.aiFunctionName){const {data,error}=await supa.functions.invoke(C.aiFunctionName,{body:{message:q,goals:S.goals.map(g=>({name:g.name,weekly:g.weekly,priority:g.priority})),insights:report().completed}});if(!error&&typeof data?.answer==='string')answer=data.answer.slice(0,2000)}}catch(err){}if(!answer)answer=coachAnswer(q);change(s=>s.chat.push({role:'assistant',text:answer,at:Date.now()}),false);chatBusy=false;render()}
async function initSupabase(){if(!C.supabaseUrl||!C.supabaseAnonKey)return;try{const mod=await import('https://esm.sh/@supabase/supabase-js@2.49.4');supa=mod.createClient(C.supabaseUrl,C.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data:{session}}=await supa.auth.getSession();if(session)await loadCloudState();supa.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'&&session)setTimeout(loadCloudState,0);if(event==='SIGNED_OUT'){cloudStatus='local';S=baseState();save();render()}})}catch(e){console.warn('Supabase indisponível:',e.message);notify('Conexão de nuvem indisponível. Seus dados locais seguem salvos.') }}
async function loadCloudState(){if(!supa)return;const {data:auth,error:authError}=await supa.auth.getUser();if(authError||!auth?.user)return;const {data,error}=await supa.from('evolve_workspaces').select('data').eq('user_id',auth.user.id).maybeSingle();if(error){notify('Não foi possível carregar o espaço da nuvem: '+error.message);return}if(data?.data?.version===2){S=data.data;S.mode='cloud'}else{S=baseState();S.mode='cloud';await supa.from('evolve_workspaces').upsert({user_id:auth.user.id,data:S})}cloudStatus='connected';save();render();notify('Seu espaço privado foi carregado da nuvem.')}
async function saveCloud(){if(!supa||cloudStatus!=='connected')return;try{const {data:auth}=await supa.auth.getUser();if(!auth?.user)return;const {error}=await supa.from('evolve_workspaces').upsert({user_id:auth.user.id,data:S});if(error)console.warn('Não foi possível sincronizar:',error.message)}catch(e){console.warn('Falha de sincronização:',e.message)}}
async function loginWithEmail(email){if(!supa){notify('Supabase não configurado pelo administrador.');return}const {error}=await supa.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname}});if(error)notify('Erro no acesso: '+error.message);else{modal='';render();notify('Enviamos um link de acesso para seu e-mail.') }}
async function googleReady(){if(window.google?.accounts?.oauth2)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error('Biblioteca Google indisponível'));document.head.append(s)})}
async function googleAuth(){if(!C.googleClientId){notify('Conexão Google requer configuração do administrador.');return false}try{await googleReady();return await new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:C.googleClientId,scope:'https://www.googleapis.com/auth/calendar.events',callback:r=>{if(r.error){reject(new Error(r.error));return}googleToken=r.access_token;render();notify('Google Calendar autorizado nesta sessão.');resolve(true)},error_callback:r=>reject(new Error(r.type||'Acesso cancelado'))});client.requestAccessToken({prompt:'consent'})})}catch(e){notify('Falha na autorização: '+e.message);return false}}
async function readGoogleBusy(){if(!googleToken){const ok=await googleAuth();if(!ok)return}try{const begin=new Date(today()+'T00:00:00'),end=new Date(plus(today(),29)+'T23:59:59');let url='https://www.googleapis.com/calendar/v3/calendars/primary/events?singleEvents=true&maxResults=250&timeMin='+encodeURIComponent(begin.toISOString())+'&timeMax='+encodeURIComponent(end.toISOString());let all=[];for(let i=0;i<5;i++){const response=await fetch(url,{headers:{Authorization:'Bearer '+googleToken}});if(!response.ok){if(response.status===401)googleToken='';throw Error('Google respondeu '+response.status)}const obj=await response.json();all.push(...(obj.items||[]));if(!obj.nextPageToken)break;url='https://www.googleapis.com/calendar/v3/calendars/primary/events?singleEvents=true&maxResults=250&timeMin='+encodeURIComponent(begin.toISOString())+'&timeMax='+encodeURIComponent(end.toISOString())+'&pageToken='+encodeURIComponent(obj.nextPageToken)}let busy=[];for(const x of all){if(x.status==='cancelled'||x.transparency==='transparent'||x.extendedProperties?.private?.evolveId)continue;if(!x.start?.dateTime)continue;const start=new Date(x.start.dateTime),stop=new Date(x.end?.dateTime||start);let duration=Math.ceil((stop-start)/60000);if(duration<=0)continue;busy.push({date:key(start),time:clock(start.getHours()*60+start.getMinutes()),duration:duration,title:x.summary||'Ocupado'})}googleBusy=busy;notify(`Google consultado: ${busy.length} compromisso(s) ocupados identificados.`)}catch(e){notify('Não foi possível ler o Google Calendar: '+e.message)}}
async function syncGoogle(){if(googleLoading)return;if(!C.googleClientId){notify('Google Calendar ainda não foi configurado. Use o arquivo .ics para testar.');return}if(!googleToken){const ok=await googleAuth();if(!ok)return}const upcoming=S.events.filter(e=>e.status!=='skipped'&&!e.googleId&&e.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!upcoming.length){notify('Nenhum evento novo para sincronizar.');return}if(!confirm(`Deseja criar ${upcoming.length} evento(s) na sua agenda principal do Google? Esta ação não é automática e poderá gerar notificações.`))return;googleLoading=true;let ok=0,fail=0;for(const e of upcoming){const start=calendarDate(e),end=new Date(start.getTime()+e.duration*60000);try{const r=await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events',{method:'POST',headers:{Authorization:'Bearer '+googleToken,'Content-Type':'application/json'},body:JSON.stringify({summary:e.title,description:'Atividade planejada pelo EVOLVE Beta. Atualizações posteriores não são refletidas automaticamente.',start:{dateTime:start.toISOString()},end:{dateTime:end.toISOString()},extendedProperties:{private:{evolveId:e.id}}})});if(!r.ok)throw Error(String(r.status));const data=await r.json();e.googleId=data.id;ok++}catch(err){fail++;if(String(err.message)==='401'){googleToken='';break}}}googleLoading=false;save();render();notify(`${ok} evento(s) criado(s) no Google${fail?' · '+fail+' não enviados':''}. Alterações futuras devem ser feitas também no Google.`)}
async function submitFeedback(fd){const rating=Number(fd.get('rating')),message=String(fd.get('message')||'').trim().slice(0,1000);if(!message)return;S.feedback.push({rating,message,date:today()});save();const title=encodeURIComponent(`[Beta] Feedback de experiência (${rating}/5)`);const body=encodeURIComponent(`Avaliação: ${rating}/5\n\nFeedback:\n${message}\n\n(Enviado a partir do app EVOLVE Beta, após revisão do usuário.)`);const url=`https://github.com/opedromoedas/EVOLVE/issues/new?title=${title}&body=${body}`;modal='';render();window.open(url,'_blank','noopener,noreferrer');notify('Feedback salvo localmente; finalize o envio na página do GitHub.')}
async function importBackup(file){try{const raw=await file.text();if(raw.length>4e6)throw Error('Arquivo muito grande');const data=JSON.parse(raw);const st=data.state||data;if(st.version!==2||!st.profile||!Array.isArray(st.goals)||!Array.isArray(st.events)||!st.logs)throw Error('Este backup não é compatível com EVOLVE Beta');if(!confirm('Importar este backup substituirá os dados do seu espaço atual. Continuar?'))return;S=st;save();render();notify('Backup importado.') }catch(err){notify('Erro na importação: '+err.message)}}
async function performAction(a,el){const id=el.dataset.id;switch(a){case'theme':setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');render();break;
 case'new-goal':openModal('goal');break;case'edit-goal':openModal('goal',id);break;case'new-event':openModal('event');break;case'edit-event':openModal('event',id);break;case'close-modal':modal='';render();break;case'modal-backdrop':if(el.classList.contains('modal-backdrop')){modal='';render()}break;
 case'delete-goal':if(confirm('Excluir esta meta? Atividades vinculadas serão preservadas no histórico.')){change(s=>s.goals=s.goals.filter(g=>g.id!==id));modal='';render()}break;
 case'delete-event':if(confirm('Excluir esta atividade? Um evento já enviado ao Google precisará ser excluído separadamente.')){change(s=>s.events=s.events.filter(g=>g.id!==id));modal='';render()}break;
 case'skip-event':change(s=>{const x=s.events.find(x=>x.id===id);if(x)x.status='skipped'});modal='';render();break;
 case'task-toggle':change(s=>{const x=s.events.find(x=>x.id===id);if(x)x.status=x.status==='done'?'planned':'done'});notify('Registro atualizado.');break;
 case'generate-plan':if(!S.goals.length){notify('Crie ao menos uma meta antes de gerar o plano.');go('goals')}else generatePlan();break;
 case'apply-plan':applyPlan();break;case'replan':replan();break;
 case'goal-day':el.classList.toggle('selected');break;
 case'office-day':{const d=Number(el.dataset.daynum);change(s=>{const a=s.profile.officeDays; if(a.includes(d))s.profile.officeDays=a.filter(x=>x!==d);else s.profile.officeDays.push(d)});break;}
 case'ob-next':if(onboardStep===0){const v=textValue($('#welcome-name'));if(!v){notify('Informe como deseja ser chamado.');return}S.profile.name=v;save()}onboardStep=Math.min(2,onboardStep+1);render();break;
 case'ob-prev':onboardStep=Math.max(0,onboardStep-1);render();break;
 case'select-prio':{const prio=el.dataset.prio;const a=S.profile.priorities;S.profile.priorities=a.includes(prio)?a.filter(x=>x!==prio):[...a,prio].slice(-3);save();render();break}
 case'finish-ob':finishOnboarding();break;
 case'try-demo':S=sampleState();save();render();notify('Demonstração carregada. Crie um plano para ver a agenda funcionando.');break;
 case'week-prev':selected=plus(selected,-7);render();break;case'week-next':selected=plus(selected,7);render();break;
 case'day-prev':selected=plus(selected,-1);render();break;case'day-next':selected=plus(selected,1);render();break;
 case'export-ics':exportICS();break;case'backup':backup();break;case'export-csv':exportCSV();break;case'share-summary':shareSummary();break;
 case'import-backup':$('#backup-file')?.click();break;
 case'reset':if(confirm('Apagar TODAS as metas, atividades e registros deste espaço? Faça um backup antes.')){S=baseState();save();view='home';render()}break;
 case'login':openModal('login');break;case'logout':if(supa&&confirm('Sair da sua conta neste dispositivo?'))await supa.auth.signOut();break;
 case'google-auth':await googleAuth();break;case'google-busy':await readGoogleBusy();break;case'sync-google':await syncGoogle();break;
 case'feedback':openModal('feedback');break;}
}
document.addEventListener('click',async ev=>{const navTarget=ev.target.closest('[data-nav]');if(navTarget){go(navTarget.dataset.nav);return}const day=ev.target.closest('[data-day]');if(day){selected=day.dataset.day;render();return}const coach=ev.target.closest('[data-coach]');if(coach){await askCoach(coach.dataset.coach);return}const target=ev.target.closest('[data-action]');if(target)await performAction(target.dataset.action,target)});
document.addEventListener('submit',async ev=>{if(!ev.target.id)return;ev.preventDefault();const fd=new FormData(ev.target);switch(ev.target.id){case'goal-form':goalForm(fd);break;case'event-form':eventForm(fd);break;case'checkin-form':change(s=>s.logs[selected]={sleep:fd.get('sleep')===''?null:clamp(Number(fd.get('sleep')),0,16),energy:fd.get('energy')===''?null:clamp(Number(fd.get('energy')),1,5),water:fd.get('water')===''?null:clamp(Number(fd.get('water')),0,30),meals:fd.get('meals')===''?null:clamp(Number(fd.get('meals')),0,10),mood:fd.get('mood')===''?null:clamp(Number(fd.get('mood')),1,5),notes:String(fd.get('notes')||'').slice(0,1500)});notify('Check-in diário salvo.');break;
 case'profile-form':change(s=>{s.profile.name=String(fd.get('name')).trim().slice(0,55);s.profile.wake=String(fd.get('wake'));s.profile.sleep=String(fd.get('sleep'));s.profile.workStart=String(fd.get('workStart'));s.profile.workEnd=String(fd.get('workEnd'));s.profile.commute=clamp(Number(fd.get('commute')),0,240)});notify('Preferências salvas.');break;
 case'review-form':{const w=currentWeek();change(s=>{const idx=s.reviews.findIndex(x=>x.week===w.start),entry={week:w.start,wins:String(fd.get('wins')||'').slice(0,1500),obstacles:String(fd.get('obstacles')||'').slice(0,1500),adjust:String(fd.get('adjust')||'').slice(0,1500),updated:today()};if(idx>=0)s.reviews[idx]=entry;else s.reviews.push(entry)});notify('Revisão salva.');break}
 case'chat-form':{const text=String(fd.get('message')||'').trim();ev.target.reset();await askCoach(text);break}
 case'login-form':await loginWithEmail(String(fd.get('email')||'').trim());break;
 case'feedback-form':await submitFeedback(fd);break;
 }});
document.addEventListener('change',async e=>{if(e.target.id==='backup-file'&&e.target.files?.[0]){await importBackup(e.target.files[0]);e.target.value=''}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal='';render()}});
render();initSupabase();if('serviceWorker'in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn(e)));
})();
